// The support module generated Lua requires (docs/more-languages.md, "Lua"): arrays that count from 0
// and keep their length, ordered sets and maps, the semantics' number formatting and conversions,
// classes, event dispatchers and the latent queue. Run writes it next to the launcher; placement
// keeps a copy beside generated files, as Go's runtime file is kept.
export const LUA_RUNTIME_FILE = 'vgraph_runtime.lua';
export const LUA_RUNTIME_MODULE = 'vgraph_runtime';

export function luaRuntime(): string {
  return `${LUA_RUNTIME}\n`;
}

const LUA_RUNTIME = String.raw`-- Support code for Lua generated by Blueprint Visual Scripting (docs/more-languages.md).
-- Generated modules require it as "vgraph_runtime". Do not edit: it is rewritten when graphs are compiled.
local vg = {}

-- ---- Arrays ---------------------------------------------------------------------------------------
-- A graph's array: items at 1..n, with n kept, so nil items count; nodes index it from 0.

local Array = { __vg_kind = "array" }
Array.__index = Array
vg.Array = Array

function vg.array(...)
  return setmetatable(table.pack(...), Array)
end

-- An array of a Lua list's items (1..count).
function vg.array_of(list, count)
  local array = setmetatable({ n = count or #list }, Array)
  for i = 1, array.n do array[i] = list[i] end
  return array
end

function vg.check_index(array, index)
  if math.type(index) == nil or index < 0 or index >= array.n then error("Index out of range", 0) end
end

-- ---- Sets -----------------------------------------------------------------------------------------
-- Sets have no order of their own: they print and turn into arrays in ascending order.

local Set = { __vg_kind = "set" }
Set.__index = Set
vg.Set = Set

function vg.set(...)
  local set = setmetatable({ items = {}, size = 0 }, Set)
  for i = 1, select("#", ...) do set:add((select(i, ...))) end
  return set
end

function Set:add(item)
  if not self.items[item] then
    self.items[item] = true
    self.size = self.size + 1
  end
end

function Set:remove(item)
  if item == nil or not self.items[item] then return false end
  self.items[item] = nil
  self.size = self.size - 1
  return true
end

function Set:clear()
  self.items = {}
  self.size = 0
end

function Set:contains(item)
  return item ~= nil and self.items[item] == true
end

function Set:sorted()
  local list = {}
  for item in pairs(self.items) do list[#list + 1] = item end
  table.sort(list, vg.less)
  return vg.array_of(list)
end

-- ---- Maps -----------------------------------------------------------------------------------------
-- Maps keep their keys in the order they were added, as the semantics require.

local Map = { __vg_kind = "map" }
Map.__index = Map
vg.Map = Map

-- vg.map(key1, value1, key2, value2, ...)
function vg.map(...)
  local map = setmetatable({ keys = {}, values = {}, present = {}, n = 0 }, Map)
  local count = select("#", ...)
  for i = 1, count - 1, 2 do
    local key, value = select(i, ...)
    map:put(key, value)
  end
  return map
end

function Map:put(key, value)
  if not self.present[key] then
    self.n = self.n + 1
    self.keys[self.n] = key
    self.present[key] = true
  end
  self.values[key] = value
end

function Map:remove(key)
  if key == nil or not self.present[key] then return false end
  for i = 1, self.n do
    if self.keys[i] == key then
      table.remove(self.keys, i)
      break
    end
  end
  self.present[key] = nil
  self.values[key] = nil
  self.n = self.n - 1
  return true
end

function Map:clear()
  self.keys, self.values, self.present, self.n = {}, {}, {}, 0
end

function Map:contains(key)
  return key ~= nil and self.present[key] == true
end

function Map:get(key)
  return self.values[key]
end

function Map:key_array()
  return vg.array_of(self.keys, self.n)
end

function Map:value_array()
  local array = setmetatable({ n = self.n }, Array)
  for i = 1, self.n do array[i] = self.values[self.keys[i]] end
  return array
end

-- A float wired into an int: truncated toward zero, an integer when it fits (NaN and the infinities stay).
function vg.trunc(x)
  local whole = x >= 0 and math.floor(x) or math.ceil(x)
  return math.tointeger(whole) or whole
end

-- Ascending order for sorting: numbers and text as Lua compares them, false before true.
function vg.less(a, b)
  if type(a) == "boolean" then return (not a) and b end
  return a < b
end

-- ---- Structs, enums, classes and interfaces --------------------------------------------------------

-- A struct type: its values print each field by name, in order (fields are {name, key} pairs).
function vg.struct(name, fields)
  local struct = { __vg_name = name, __vg_fields = fields }
  struct.__index = struct
  return struct
end

-- A class. Its module sets its parent as its metatable's __index, so functions are found up the
-- parent chain: they are virtual, as in Unreal.
function vg.class(name)
  local class = { __vg_name = name, __vg_interfaces = {} }
  class.__index = class
  return class
end

function vg.interface(name)
  return { __vg_name = name, __vg_interface = true }
end

-- Cast To: whether the value is an object of the class, or of a class that implements the interface.
function vg.is_a(value, type_)
  if type(value) ~= "table" then return false end
  local class = getmetatable(value)
  while class do
    if class == type_ then return true end
    local implements = rawget(class, "__vg_interfaces")
    if implements and implements[type_] then return true end
    local up = getmetatable(class)
    class = up and up.__index
  end
  return false
end

-- ---- Event dispatchers ----------------------------------------------------------------------------
-- Bound events (an object and its function) run in the order they were bound, each once.

local Dispatcher = {}
Dispatcher.__index = Dispatcher

function vg.dispatcher()
  return setmetatable({ handlers = {} }, Dispatcher)
end

function Dispatcher:bind(object, method)
  for _, handler in ipairs(self.handlers) do
    if handler[1] == object and handler[2] == method then return end
  end
  self.handlers[#self.handlers + 1] = { object, method }
end

function Dispatcher:unbind(object, method)
  for i, handler in ipairs(self.handlers) do
    if handler[1] == object and handler[2] == method then
      table.remove(self.handlers, i)
      return
    end
  end
end

function Dispatcher:clear()
  self.handlers = {}
end

function Dispatcher:broadcast(...)
  local handlers = { table.unpack(self.handlers) }
  for _, handler in ipairs(handlers) do handler[2](handler[1], ...) end
end

-- ---- Latent actions -------------------------------------------------------------------------------
-- Delay's actions, of every class, run from one queue in the order they fall due, once Start (and
-- Main) have returned. Lua has no sleep, so waiting watches the processor clock.

local latent = { pending = {}, order = 0 }

function vg.delay(seconds, action)
  latent.order = latent.order + 1
  latent.pending[#latent.pending + 1] = { due = os.clock() + math.max(0, seconds), order = latent.order, action = action }
end

-- An async function (---@async; docs/node-authoring.md, gap 4) runs as a coroutine: at once, until
-- it first yields, then once on each latent turn until it returns. Its Completed then joins the
-- queue with what it returned; an error in it stops the run.
latent.waiting = {}

local function step(entry)
  local ok, value = coroutine.resume(entry.co)
  if not ok then error(value, 0) end
  if coroutine.status(entry.co) ~= "dead" then return false end
  vg.delay(0, function() entry.completed(value) end)
  return true
end

function vg.await_latent(call, completed)
  local entry = { co = coroutine.create(call), completed = completed }
  if not step(entry) then latent.waiting[#latent.waiting + 1] = entry end
end

function vg.run_latent_actions()
  while #latent.pending > 0 or #latent.waiting > 0 do
    local waiting = latent.waiting
    latent.waiting = {}
    for _, entry in ipairs(waiting) do
      if not step(entry) then latent.waiting[#latent.waiting + 1] = entry end
    end
    if #latent.pending > 0 then
      table.sort(latent.pending, function(a, b)
        if a.due ~= b.due then return a.due < b.due end
        return a.order < b.order
      end)
      local next_action = latent.pending[1]
      if os.clock() >= next_action.due then
        table.remove(latent.pending, 1)
        next_action.action()
      elseif #latent.waiting == 0 then
        while os.clock() < next_action.due do end
      end
    end
  end
end

-- ---- Values (docs/semantics.md) -------------------------------------------------------------------

-- Numbers as text by JavaScript's rules: the shortest digits that read back exactly.
function vg.format_number(x)
  if x ~= x then return "NaN" end
  if x == math.huge then return "Infinity" end
  if x == -math.huge then return "-Infinity" end
  if math.type(x) == "integer" then return string.format("%d", x) end
  if x == 0 then return "0" end
  local text
  for precision = 1, 17 do
    text = string.format("%." .. (precision - 1) .. "e", x)
    if tonumber(text) == x then break end
  end
  local sign, first, rest, exponent = text:match("^(-?)(%d)%.?(%d*)e([-+]%d+)$")
  local digits = (first .. rest):gsub("0+$", "")
  if digits == "" then digits = "0" end
  local point = tonumber(exponent) + 1
  if #digits <= point and point <= 21 then return sign .. digits .. string.rep("0", point - #digits) end
  if 0 < point and point <= 21 then return sign .. digits:sub(1, point) .. "." .. digits:sub(point + 1) end
  if -6 < point and point <= 0 then return sign .. "0." .. string.rep("0", -point) .. digits end
  local mantissa = #digits > 1 and (digits:sub(1, 1) .. "." .. digits:sub(2)) or digits
  return sign .. mantissa .. "e" .. (point > 0 and "+" or "-") .. math.abs(point - 1)
end

local escapes = { ['"'] = '\\"', ["\\"] = "\\\\", ["\b"] = "\\b", ["\f"] = "\\f", ["\n"] = "\\n", ["\r"] = "\\r", ["\t"] = "\\t" }

local function quote(text)
  return '"' .. text:gsub('[%c"\\]', function(c) return escapes[c] or string.format("\\u%04x", c:byte()) end) .. '"'
end

local function key_text(key)
  if type(key) == "string" then return key end
  return vg.format(key)
end

-- Containers and structs print as JSON: sets in ascending order, maps in the order keys were added.
function vg.json(value)
  local kind = type(value)
  if value == nil then return "null" end
  if kind == "boolean" then return value and "true" or "false" end
  if kind == "number" then
    if value ~= value or value == math.huge or value == -math.huge then return "null" end
    return vg.format_number(value)
  end
  if kind == "string" then return quote(value) end
  local class = getmetatable(value)
  local parts = {}
  if class == Array then
    for i = 1, value.n do parts[i] = vg.json(value[i]) end
    return "[" .. table.concat(parts, ",") .. "]"
  end
  if class == Set then return vg.json(value:sorted()) end
  if class == Map then
    for i = 1, value.n do
      local key = value.keys[i]
      parts[i] = quote(key_text(key)) .. ":" .. vg.json(value.values[key])
    end
    return "{" .. table.concat(parts, ",") .. "}"
  end
  local fields = class and class.__vg_fields
  if fields then
    for i, field in ipairs(fields) do parts[i] = quote(field[1]) .. ":" .. vg.json(value[field[2]]) end
    return "{" .. table.concat(parts, ",") .. "}"
  end
  return quote(class and class.__vg_name or tostring(value))
end

function vg.format(value)
  local kind = type(value)
  if value == nil then return "" end
  if kind == "boolean" then return value and "true" or "false" end
  if kind == "number" then return vg.format_number(value) end
  if kind == "string" then return value end
  return vg.json(value)
end

-- Text as a number, as JavaScript's Number() reads it: blank is 0, anything else not a number NaN.
function vg.to_number(value)
  local kind = type(value)
  if value == nil then return 0 end
  if kind == "number" then return value end
  if kind == "boolean" then return value and 1 or 0 end
  if kind ~= "string" then return 0 / 0 end
  local text = value:match("^%s*(.-)%s*$")
  if text == "" then return 0 end
  local sign, word = text:match("^([-+]?)(Infinity)$")
  if word then return sign == "-" and -math.huge or math.huge end
  if text:find("^[-+]?%d*%.?%d*[eE]?[-+]?%d*$") or text:find("^0[xX]%x+$") then
    local number = tonumber(text)
    if number then return number end
  end
  return 0 / 0
end

-- Truth as the semantics define it: false, nil, 0, NaN and empty text are false.
function vg.to_boolean(value)
  if value == nil or value == false then return false end
  if type(value) == "number" then return value == value and value ~= 0 end
  if type(value) == "string" then return value ~= "" end
  return true
end

-- A text's characters (code points), as a list of strings.
function vg.chars(text)
  local list = {}
  for _, code in utf8.codes(text) do list[#list + 1] = utf8.char(code) end
  return list
end

-- An error's message, without the position Lua adds to its own errors' messages.
function vg.message(problem)
  if type(problem) == "string" then return problem end
  return vg.format(problem)
end

return vg`;
